begin;
alter table public.candidate_profiles add column share_success_story boolean not null default false;
create table public.company_profiles(id uuid primary key default gen_random_uuid(),organization_id uuid unique references public.organizations,source_id text unique references public.job_sources,name text not null check(length(trim(name)) between 1 and 160),description_he text not null default '' check(length(description_he)<=8000),description_en text not null default '' check(length(description_en)<=8000),sector text not null default '' check(length(sector)<=160),location text not null default '' check(length(location)<=240),published boolean not null default false,image_paths text[] not null default '{}',updated_at timestamptz not null default now(),check(num_nonnulls(organization_id,source_id)=1));
alter table public.company_profiles enable row level security;
create policy company_profile_public_read on public.company_profiles for select using(published);
create policy company_profile_private_read on public.company_profiles for select to authenticated using(public.is_platform_admin() or public.has_role(organization_id,array['owner','admin']));
create policy company_profile_insert on public.company_profiles for insert to authenticated with check(public.is_platform_admin() or (source_id is null and public.has_role(organization_id,array['owner','admin'])));
create policy company_profile_update on public.company_profiles for update to authenticated using(public.is_platform_admin() or public.has_role(organization_id,array['owner','admin'])) with check(public.is_platform_admin() or public.has_role(organization_id,array['owner','admin']));
revoke all on public.company_profiles from anon,authenticated;grant select on public.company_profiles to anon,authenticated;grant insert on public.company_profiles to authenticated;grant update(name,description_he,description_en,sector,location,published,image_paths,updated_at) on public.company_profiles to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('company-images','company-images',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create function public.can_edit_company(profile text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.company_profiles c where c.id::text=profile and (public.is_platform_admin() or public.has_role(c.organization_id,array['owner','admin'])))$$;
revoke all on function public.can_edit_company(text) from public,anon;grant execute on function public.can_edit_company(text) to authenticated;
create policy company_image_upload on storage.objects for insert to authenticated with check(bucket_id='company-images' and public.can_edit_company((storage.foldername(name))[1]));
create policy company_image_public_read on storage.objects for select using(bucket_id='company-images' and exists(select 1 from public.company_profiles c where c.published and storage.objects.name=any(c.image_paths)));
create policy company_image_owner_read on storage.objects for select to authenticated using(bucket_id='company-images' and public.can_edit_company((storage.foldername(name))[1]));
create function public.public_candidate_examples(job uuid,external boolean default false) returns table(display_name text,headline text) language sql stable security definer set search_path='' as $$
 select p.full_name,p.headline from public.candidate_profiles p join public.applications a on a.candidate_id=p.user_id where p.share_success_story and a.status='hired' and ((not external and a.job_id=job and exists(select 1 from public.jobs j where j.id=job and j.status='open')) or (external and a.external_job_id=job and exists(select 1 from public.external_jobs j where j.id=job and j.publication_status='published' and j.status='active' and j.verified_at>now()-interval '7 days'))) order by a.created_at desc limit 3$$;
revoke all on function public.public_candidate_examples(uuid,boolean) from public;grant execute on function public.public_candidate_examples(uuid,boolean) to anon,authenticated;
create table public.customer_testimonials(id uuid primary key default gen_random_uuid(),company text not null check(length(company) between 1 and 160),person text not null check(length(person) between 1 and 160),quote_he text not null default '' check(length(quote_he)<=2000),quote_en text not null default '' check(length(quote_en)<=2000),consent_confirmed boolean not null default false,published boolean not null default false,created_at timestamptz not null default now(),check(not published or consent_confirmed));
alter table public.customer_testimonials enable row level security;
alter table public.customer_testimonials add constraint meaningful_testimonial check(not published or length(trim(quote_he||quote_en))>0);
create policy testimonials_public_read on public.customer_testimonials for select using(published and consent_confirmed);
create policy testimonials_admin_read on public.customer_testimonials for select to authenticated using(public.is_platform_admin());
create policy testimonials_write on public.customer_testimonials for all to authenticated using(public.is_platform_admin()) with check(public.is_platform_admin());
revoke all on public.customer_testimonials from anon,authenticated;grant select on public.customer_testimonials to anon,authenticated;grant insert,update on public.customer_testimonials to authenticated;
create function public.valid_company_paths(profile uuid,paths text[]) returns boolean language sql immutable set search_path='' as $$select coalesce(bool_and(p like profile::text||'/%' and position('..' in p)=0),true) from unnest(paths) p$$;
alter table public.company_profiles add constraint valid_image_paths check(public.valid_company_paths(id,image_paths));
commit;
